"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs");
const vm = require("node:vm");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
const report = require("../sales-commission-report");
const orders = ["R1", "R2", "R3"].map((driver, i) => ({ code: `P${i}`, commissions: { calculatedAt: "2026-10-21", driver: { user: driver, baseAmount: 1000, total: 10 } } }));
const original = JSON.stringify(orders);
assert.equal(report.buildDriver(orders, { drivers: ["R1", "R3"] }).total, 20);
assert.deepEqual(report.buildDriver(orders, { drivers: ["R1", "R3"] }).drivers.map(r => r.driver), ["R1", "R3"]);
assert.equal(report.buildDriver(orders, { driver: "R2" }).total, 10);
assert.equal(report.buildDriver(orders, { drivers: [] }).total, 30);
assert.equal(report.buildDriver(orders, { drivers: ["R1", "R1"] }).total, 10);
assert.equal(report.buildDriver(orders, { from: "2026-10-22" }).total, 0);
assert.equal(JSON.stringify(orders), original);
const html = fs.readFileSync(path.join(root, "index.html"), "utf8");
assert.ok(!html.match(/<input[^>]+id="clientCreditLimitInput"[^>]*>/)[0].includes("required"));
const app = fs.readFileSync(path.join(root, "app.js"), "utf8");
const dateExpression = app.match(/const matchesDate = ([\s\S]*?);\r?\n  const amount/)[1];
const matches = (recordDate, bankDateFilter, bankDateToFilter) => vm.runInNewContext(dateExpression, { recordDate, bankDateFilter, bankDateToFilter });
assert.ok(matches("2026-10-01", "2026-10-01", "2026-10-21"));
assert.ok(matches("2026-10-21", "2026-10-01", "2026-10-21"));
assert.ok(!matches("2026-10-22", "2026-10-01", "2026-10-21"));
assert.ok(!matches("", "2026-10-01", ""));
assert.ok(matches("2026-09-30", "", "2026-10-21"));
const ui = fs.readFileSync(path.join(root, "collection-visits-ui.js"), "utf8");
const code = ui.slice(ui.indexOf("function renderCollectionVisitPlacement"), ui.indexOf("function renderCollectionVisits()"));
const panel = {};
const state = { collectionVisits: [{ id: "V1", client: "One", amount: 100, status: "Pendiente", payments: [] }, { id: "V2", client: "Two", routeId: "R1", amount: 200, payments: [] }], deliveryRoutes: [{ id: "R1" }] };
const before = JSON.stringify(state);
const ctx = { state, byId: () => panel, isAdminUser: () => true, isDeliveryRouteClosed: () => false, escapeHtml: String, money: { format: String }, DeliveryEngine: { routeDisplayName: r => r.id } };
vm.createContext(ctx); vm.runInContext(code, ctx);
ctx.renderCollectionVisitPlacement({ id: "planner" }, "");
assert.ok(panel.innerHTML.includes("V1")); assert.ok(!panel.innerHTML.includes("V2"));
ctx.renderCollectionVisitPlacement({ id: "stops" }, "R1");
assert.ok(panel.innerHTML.includes("V2")); assert.ok(!panel.innerHTML.includes("V1"));
ctx.renderCollectionVisitPlacement({ id: "stops" }, null); assert.equal(panel.hidden, true);
assert.equal(JSON.stringify(state), before);
console.log("PASS feedback: multi-driver filters, optional limit, inclusive date range, collection visibility, no record mutation");
